// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, uint8 dataSize) public {
        vm.assume(amount > 0 && amount <= 1000 ether);
        vm.assume(dataSize > 0 && dataSize <= 100);
        bytes memory data = new bytes(dataSize);
        Target target = new Target();
        vm.deal(address(c), 1001 ether);
        vm.prank(c.Owner());
        uint256 preBalance = address(target).balance;
        c.Command{value: amount}(address(target), data);
        uint256 postBalance = address(target).balance;
        assertTrue(postBalance == preBalance + amount);
    }
}

contract Target {
    fallback() external payable {}
}
